CREATE TABLE users(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,username VARCHAR(32) UNIQUE NOT NULL,password_hash VARCHAR(100) NOT NULL,display_name VARCHAR(64) NOT NULL,role VARCHAR(16) NOT NULL,disabled BOOLEAN NOT NULL,created_at TIMESTAMP WITH TIME ZONE NOT NULL);
CREATE TABLE workspaces(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,name VARCHAR(64) UNIQUE NOT NULL,created_by BIGINT NOT NULL,created_at TIMESTAMP WITH TIME ZONE NOT NULL);
CREATE TABLE memberships(workspace_id BIGINT NOT NULL,user_id BIGINT NOT NULL,role VARCHAR(16) NOT NULL,created_at TIMESTAMP WITH TIME ZONE NOT NULL,PRIMARY KEY(workspace_id,user_id));
CREATE TABLE groups(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,workspace_id BIGINT NOT NULL,name VARCHAR(64) NOT NULL,is_default BOOLEAN NOT NULL,created_at TIMESTAMP WITH TIME ZONE NOT NULL);
CREATE TABLE projects(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,workspace_id BIGINT NOT NULL,group_id BIGINT NOT NULL,name VARCHAR(64) NOT NULL,created_at TIMESTAMP WITH TIME ZONE NOT NULL);
CREATE TABLE project_acl(workspace_id BIGINT NOT NULL,project_id BIGINT NOT NULL,user_id BIGINT NOT NULL,role VARCHAR(16) NOT NULL,updated_at TIMESTAMP WITH TIME ZONE NOT NULL,PRIMARY KEY(workspace_id,project_id,user_id));
ALTER TABLE users ALTER COLUMN id RESTART WITH 100;
ALTER TABLE workspaces ALTER COLUMN id RESTART WITH 100;
ALTER TABLE groups ALTER COLUMN id RESTART WITH 100;
ALTER TABLE projects ALTER COLUMN id RESTART WITH 100;
